import sys

def main():
    n = int(sys.stdin.readline().strip())
    A = list(map(int, sys.stdin.readline().strip().split()))

    count = 0
    for i in range(n):
        left, right = i + 1, n - 1
        while left <= right:
            mid = (left + right) // 2
            if A[mid] <= 2 * A[i]:
                left = mid + 1
            else:
                right = mid - 1
        count += right - i

    print(count)

if __name__ == "__main__":
    main()

